window.FIG_SERIES=window.FIG_SERIES||{};window.FIG_SERIES["FIG-19de9c0be9c5e7fd"]={"versions": [{"id": "FIG-19de9c0be9c5e7fd", "releases": ["R4.0.3"], "html": "<h4 class=\"fig-section-h4\">1. Diagrammtyp &amp; Architektur-Kontext</h4>\n<ul class=\"fig-list\"><li><strong>Klassifikation:</strong> Sequenzdiagramm / Timing-Ablaufdiagramm (AUTOSAR-spezifische Darstellung mit Lebenslinien und asynchronen Trigger-Ereignissen über der Zeitachse t).\n</li><li><strong>Funktionale Einordnung:</strong> AUTOSAR Classic Platform BSW, Communication Stack (ComStack). Das Diagramm spezifiziert das Verhalten des <strong>FlexRay ISO Transport Layer (FrTp / ISO 10681-2)</strong> bei einem vorzeitigen Sendeabbruch (<em>Transmit Cancellation</em>) einer unsegmentierten Botschaft (<em>Single Frame</em> / SF).\n</li><li><strong>Zweck:</strong> Darstellung des Entkopplungs- und Abbruchmechanismus zwischen oberer Schicht (<strong>PDU Router / PduR</strong>) und FrTp-Sendepuffer, bevor Daten auf den FlexRay-Bus bzw. an das <strong>FlexRay Interface (FrIf)</strong> übergeben werden.\n</li></ul>\n<hr class=\"fig-divider\" />\n<h4 class=\"fig-section-h4\">2. Komponenten, Entitäten &amp; Schnittstellen</h4>\n<ul class=\"fig-list\"><li><strong>Beteiligte Entitäten:</strong>\n<ul class=\"fig-list\"><li><strong>FrTp Sender:</strong> Lokale Instanz des FlexRay Transport Layers auf dem Sende-Steuergerät (verwaltet Verbindungskontexte, Puffer und State-Machines).\n</li><li><strong>FrTp Receiver:</strong> Peer-Instanz auf dem Ziel-Knoten (im Diagramm als leere Lebenslinie dargestellt, da kein Buszugriff stattfindet).\n</li><li><strong>PduR (impliziter oberer Kommunikationspartner):</strong> Quelle der Sende- und Abbruchanforderungen sowie Empfänger der Bestätigung.\n</li></ul>\n</li><li><strong>Schnittstellen &amp; Service-APIs:</strong>\n<ul class=\"fig-list\"><li><code>FrTp_Transmit(PduIdType TxPduId, const PduInfoType* PduInfoPtr)</code>: Service-Aufruf des PduR zur Initiierung der Übertragung.\n</li><li><code>FrTp_TransmitCancellation(PduIdType TxPduId)</code>: Steueranforderung des PduR zum Verwerfen einer ausstehenden PDU.\n</li><li><code>FrTp_MainFunction()</code>: Zyklischer BSW-Scheduler-Task (Schedule Manager / SchM) zur internen Zustandsfortschreibung und asynchronen Benachrichtigung.\n</li><li><code>PduR_FrTpTxConfirmation(PduIdType TxPduId, Std_ReturnType Result)</code>: Callback-Schnittstelle von FrTp an PduR zur Mitteilung des Übertragungsergebnisses.\n</li></ul>\n</li></ul>\n<hr class=\"fig-divider\" />\n<h4 class=\"fig-section-h4\">3. Dynamisches Verhalten &amp; Sequenzablauf</h4>\n<ol class=\"fig-list\"><li><strong>Sendeinitiierung (<code>FrTp_Transmit</code>):</strong>\n<ul class=\"fig-list\"><li>PduR ruft synchron <code>FrTp_Transmit</code> auf. FrTp belegt den internen Sende-Verbindungskanal (<em>Channel State Machine</em>) und markiert die unsegmentierte PDU für den Versand im nächsten Scheduler-Zyklus.\n</li></ul>\n</li><li><strong>Abbruchanforderung (<code>FrTp_TransmitCancellation</code>):</strong>\n<ul class=\"fig-list\"><li>Noch vor der Übergabe an das FlexRay Interface (<code>FrIf_Transmit</code>) fordert PduR den Abbruch via <code>FrTp_TransmitCancellation(TxPduId)</code> an.\n</li><li>Der Funktionsaufruf quittiert die Annahme des Abbruchs synchron (sofern konfiguriert und die PDU noch im Puffer vorliegt). Der physische Versand wird blockiert; es erfolgt <strong>keine</strong> Interaktion mit dem <em>FrTp Receiver</em> über das Netzwerk.\n</li></ul>\n</li><li><strong>Zyklische Verarbeitung (<code>FrTp_MainFunction</code>):</strong>\n<ul class=\"fig-list\"><li>Der BSW-Scheduler triggert die zyklische Task <code>FrTp_MainFunction()</code>.\n</li><li>FrTp erkennt die Cancellation-Markierung der unsegmentierten PDU, löscht die Kanalbelegung, setzt den Sende-Zustand zurück und gibt reservierte Pufferressourcen frei.\n</li></ul>\n</li><li><strong>Ergebnisquittierung (<code>PduR_FrTpTxConfirmation</code>):</strong>\n<ul class=\"fig-list\"><li>FrTp benachrichtigt die obere Schicht über <code>PduR_FrTpTxConfirmation(TxPduId, E_NOT_OK)</code>. Der negative Status signalisiert dem PduR die Nichtübertragung infolge des Abbruchs.\n</li></ul>\n</li></ol>\n<hr class=\"fig-divider\" />\n<h4 class=\"fig-section-h4\">4. Normative Relevanz &amp; Entwickler-Hinweise</h4>\n<ul class=\"fig-list\"><li><strong>Asynchroner Abschluss:</strong> <code>FrTp_TransmitCancellation</code> bricht die Übertragung nicht unmittelbar mit synchroner PduR-Rückmeldung ab. Das endgültige Schließen des Transaktionskontextes und die Rückmeldung <code>PduR_FrTpTxConfirmation(..., E_NOT_OK)</code> erfolgen zwingend im Kontext der <code>FrTp_MainFunction</code>.\n</li><li><strong>Ressourcenfreigabe:</strong> Ein Re-Transmit derselben PduId durch PduR darf erst erfolgen, nachdem das Callback <code>PduR_FrTpTxConfirmation</code> empfangen wurde, um Race Conditions auf der Kanal-State-Machine zu verhindern.\n</li><li><strong>Konfigurationsabhängigkeit:</strong>\n<ul class=\"fig-list\"><li>Der Parameter <code>FrTpCancellation</code> (bzw. <code>FrTpTxCancellation</code>) muss im BSW-Modul-Design auf <code>TRUE</code> konfiguriert sein, andernfalls liefert <code>FrTp_TransmitCancellation</code> den Fehlercode <code>E_NOT_OK</code> oder ist nicht generiert.\n</li><li>Das Timing zwischen Abbruchanforderung und Ausführung hängt direkt von der Periode des Main-Function-Zyklus (<code>FrTpMainFunctionPeriod</code>) ab.\n</li></ul>\n</li><li><strong>Pufferzustand im FrIf/Treiber:</strong> Das Diagramm bildet den Gutfall ab, bei dem der Frame den FrTp noch nicht in Richtung <code>FrIf</code> verlassen hat. Sobald FrTp bereits <code>FrIf_Transmit()</code> aufgerufen hat, ist ein Abbruch über diesen Pfad im ISO-Transport-Layer für unsegmentierten Transfer nicht mehr garantiert busneutral möglich.\n</li></ul>", "model": "gemini-3.8-flash (via agy)"}, {"id": "FIG-960de3ef7fe55f9d", "releases": ["R4.1.3"], "html": "<h4 class=\"fig-section-h4\">1. Diagrammtyp &amp; Architektur-Kontext</h4>\n<ul class=\"fig-list\"><li><strong>Klassifikation:</strong> Sequenzdiagramm / Timing-Ablaufdiagramm (AUTOSAR-spezifische Darstellung mit Lebenslinien und asynchronen Trigger-Ereignissen über der Zeitachse t).\n</li><li><strong>Funktionale Einordnung:</strong> AUTOSAR Classic Platform BSW, Communication Stack (ComStack). Das Diagramm spezifiziert das Verhalten des <strong>FlexRay ISO Transport Layer (FrTp / ISO 10681-2)</strong> bei einem vorzeitigen Sendeabbruch (<em>Transmit Cancellation</em>) einer unsegmentierten Botschaft (<em>Single Frame</em> / SF).\n</li><li><strong>Zweck:</strong> Darstellung des Entkopplungs- und Abbruchmechanismus zwischen oberer Schicht (<strong>PDU Router / PduR</strong>) und FrTp-Sendepuffer, bevor Daten auf den FlexRay-Bus bzw. an das <strong>FlexRay Interface (FrIf)</strong> übergeben werden.\n</li></ul>\n<h4 class=\"fig-section-h4\">2. Komponenten, Entitäten &amp; Schnittstellen</h4>\n<ul class=\"fig-list\"><li><strong>Beteiligte Entitäten:</strong>\n<ul class=\"fig-list\"><li><strong>FrTp Sender:</strong> Lokale Instanz des FlexRay Transport Layers auf dem Sende-Steuergerät (verwaltet Verbindungskontexte, Puffer und State-Machines).\n</li><li><strong>FrTp Receiver:</strong> Peer-Instanz auf dem Ziel-Knoten (im Diagramm als leere Lebenslinie dargestellt, da kein Buszugriff stattfindet).\n</li><li><strong>PduR (impliziter oberer Kommunikationspartner):</strong> Quelle der Sende- und Abbruchanforderungen.\n</li></ul>\n</li><li><strong>Schnittstellen &amp; Service-APIs:</strong>\n<ul class=\"fig-list\"><li><code>FrTp_Transmit(PduIdType TxPduId, const PduInfoType* PduInfoPtr)</code>: Service-Aufruf des PduR zur Initiierung der Übertragung.\n</li><li><code>FrTp_TransmitCancel(PduIdType TxPduId)</code>: Steueranforderung des PduR zum Verwerfen einer ausstehenden PDU vor deren physischer Aussendung.\n</li></ul>\n</li></ul>\n<h4 class=\"fig-section-h4\">3. Dynamisches Verhalten &amp; Sequenzablauf</h4>\n<ol class=\"fig-list\"><li><strong>Sendeinitiierung (<code>FrTp_Transmit</code>):</strong>\n<ul class=\"fig-list\"><li>PduR ruft synchron <code>FrTp_Transmit</code> am FrTp Sender auf. FrTp belegt den internen Sende-Verbindungskanal (<em>Channel State Machine</em>) und bereitet die unsegmentierte PDU für den Versand vor.\n</li></ul>\n</li><li><strong>Abbruchanforderung (<code>FrTp_TransmitCancel</code>):</strong>\n<ul class=\"fig-list\"><li>Noch vor der Übergabe an das FlexRay Interface (<code>FrIf_Transmit</code>) fordert PduR den Abbruch via <code>FrTp_TransmitCancel(TxPduId)</code> an.\n</li><li>FrTp bricht den Übertragungsauftrag ab; es erfolgt keine Datenübertragung auf den FlexRay-Bus und somit keine Interaktion mit dem <em>FrTp Receiver</em>.\n</li></ul>\n</li></ol>\n<h4 class=\"fig-section-h4\">4. Normative Relevanz &amp; Entwickler-Hinweise</h4>\n<ul class=\"fig-list\"><li><strong>API-Benennung:</strong> Die Abbruchfunktion wird als <code>FrTp_TransmitCancel</code> bezeichnet (im Unterschied zu älteren Fassungen mit <code>FrTp_TransmitCancellation</code>).\n</li><li><strong>Schnittstellenfokus:</strong> Das Diagramm visualisiert ausschließlich den Aufruf von <code>FrTp_Transmit</code> und den darauffolgenden Abbruch über <code>FrTp_TransmitCancel</code>; asynchrone Fortschreibungen im Kontext einer MainFunction oder explizite Tx-Confirmations werden in dieser Fassung nicht dargestellt.\n</li><li><strong>Konfigurationsabhängigkeit:</strong> Die Verfügbarkeit der Abbruchfunktion erfordert die Aktivierung der entsprechenden Transmit-Cancellation-Unterstützung in der FrTp-BSW-Konfiguration.\n</li><li><strong>Puffer- und Sendezustand:</strong> Transmit Cancellation für unsegmentierte Übertragungen greift nur, solange die PDU noch nicht an das unterlagerte FlexRay Interface (<code>FrIf</code>) übergeben bzw. von diesem verarbeitet wurde.\n</li></ul>", "model": "gemini-3.8-flash (via agy)"}, {"id": "FIG-8969dbd85dd7247b", "releases": ["R4.2.2"], "html": "<h4 class=\"fig-section-h4\">1. Diagrammtyp &amp; Architektur-Kontext</h4>\n<ul class=\"fig-list\"><li><strong>Klassifikation:</strong> Sequenzdiagramm / Timing-Ablaufdiagramm (AUTOSAR-spezifische Darstellung mit Lebenslinien und asynchronen Trigger-Ereignissen über der Zeitachse t).\n</li><li><strong>Funktionale Einordnung:</strong> AUTOSAR Classic Platform BSW, Communication Stack (ComStack). Das Diagramm spezifiziert das Verhalten des <strong>FlexRay ISO Transport Layer (FrTp / ISO 10681-2)</strong> bei einem vorzeitigen Sendeabbruch (<em>Transmit Cancellation</em>) einer unsegmentierten Botschaft (<em>Single Frame</em> / SF).\n</li><li><strong>Zweck:</strong> Darstellung des Entkopplungs- und Abbruchmechanismus zwischen oberer Schicht (<strong>PDU Router / PduR</strong>) und FrTp-Sendepuffer, bevor Daten auf den FlexRay-Bus bzw. an das <strong>FlexRay Interface (FrIf)</strong> übergeben werden.\n</li></ul>\n<h4 class=\"fig-section-h4\">2. Komponenten, Entitäten &amp; Schnittstellen</h4>\n<ul class=\"fig-list\"><li><strong>Beteiligte Entitäten:</strong>\n<ul class=\"fig-list\"><li><strong>FrTp Sender:</strong> Lokale Instanz des FlexRay Transport Layers auf dem Sende-Steuergerät (verwaltet Verbindungskontexte, Puffer und State-Machines).\n</li><li><strong>FrTp Receiver:</strong> Peer-Instanz auf dem Ziel-Knoten (im Diagramm als leere Lebenslinie dargestellt, da kein Buszugriff stattfindet).\n</li><li><strong>PduR (impliziter oberer Kommunikationspartner):</strong> Quelle der Sende- und Abbruchanforderungen.\n</li></ul>\n</li><li><strong>Schnittstellen &amp; Service-APIs:</strong>\n<ul class=\"fig-list\"><li><code>FrTp_Transmit(PduIdType TxPduId, const PduInfoType* PduInfoPtr)</code>: Service-Aufruf des PduR zur Initiierung der Übertragung.\n</li><li><code>FrTp_TransmitCancel(PduIdType TxPduId)</code>: Steueranforderung des PduR zum Verwerfen einer ausstehenden PDU vor deren physischer Aussendung.\n</li></ul>\n</li></ul>\n<h4 class=\"fig-section-h4\">3. Dynamisches Verhalten &amp; Sequenzablauf</h4>\n<ol class=\"fig-list\"><li><strong>Sendeinitiierung (<code>FrTp_Transmit</code>):</strong>\n<ul class=\"fig-list\"><li>PduR ruft synchron <code>FrTp_Transmit</code> am FrTp Sender auf. FrTp belegt den internen Sende-Verbindungskanal (<em>Channel State Machine</em>) und bereitet die unsegmentierte PDU für den Versand vor.\n</li></ul>\n</li><li><strong>Abbruchanforderung (<code>FrTp_TransmitCancel</code>):</strong>\n<ul class=\"fig-list\"><li>Noch vor der Übergabe an das FlexRay Interface (<code>FrIf_Transmit</code>) fordert PduR den Abbruch via <code>FrTp_TransmitCancel(TxPduId)</code> an.\n</li><li>FrTp bricht den Übertragungsauftrag ab; es erfolgt keine Datenübertragung auf den FlexRay-Bus und somit keine Interaktion mit dem <em>FrTp Receiver</em>.\n</li></ul>\n</li></ol>\n<h4 class=\"fig-section-h4\">4. Normative Relevanz &amp; Entwickler-Hinweise</h4>\n<ul class=\"fig-list\"><li><strong>API-Benennung:</strong> Die Abbruchfunktion wird als <code>FrTp_TransmitCancel</code> bezeichnet (im Unterschied zu älteren Fassungen mit <code>FrTp_TransmitCancellation</code>).\n</li><li><strong>Schnittstellenfokus:</strong> Das Diagramm visualisiert ausschließlich den Aufruf von <code>FrTp_Transmit</code> und den darauffolgenden Abbruch über <code>FrTp_TransmitCancel</code>; asynchrone Fortschreibungen im Kontext einer MainFunction oder explizite Tx-Confirmations werden in dieser Fassung nicht dargestellt.\n</li><li><strong>Konfigurationsabhängigkeit:</strong> Die Verfügbarkeit der Abbruchfunktion erfordert die Aktivierung der entsprechenden Transmit-Cancellation-Unterstützung in der FrTp-BSW-Konfiguration.\n</li><li><strong>Puffer- und Sendezustand:</strong> Transmit Cancellation für unsegmentierte Übertragungen greift nur, solange die PDU noch nicht an das unterlagerte FlexRay Interface (<code>FrIf</code>) übergeben bzw. von diesem verarbeitet wurde.\n</li></ul>", "model": "gemini-3.8-flash (via agy)"}, {"id": "FIG-f75d9cc9b0ef5f57", "releases": ["R24-11"], "html": "<h4 class=\"fig-section-h4\">1. Diagrammtyp &amp; Architektur-Kontext</h4>\n<ul class=\"fig-list\"><li><strong>Klassifikation:</strong> Sequenzdiagramm / Timing-Ablaufdiagramm (AUTOSAR-spezifische Darstellung mit Lebenslinien und asynchronen Trigger-Ereignissen über der Zeitachse t).\n</li><li><strong>Funktionale Einordnung:</strong> AUTOSAR Classic Platform BSW, Communication Stack (ComStack). Das Diagramm spezifiziert das Verhalten des <strong>FlexRay ISO Transport Layer (FrTp / ISO 10681-2)</strong> bei einem vorzeitigen Sendeabbruch (<em>Transmit Cancellation</em>) einer unsegmentierten Botschaft (<em>Single Frame</em> / SF).\n</li><li><strong>Zweck:</strong> Darstellung des Entkopplungs- und Abbruchmechanismus zwischen oberer Schicht (<strong>PDU Router / PduR</strong>) und FrTp-Sendepuffer, bevor Daten auf den FlexRay-Bus bzw. an das <strong>FlexRay Interface (FrIf)</strong> übergeben werden.\n</li></ul>\n<h4 class=\"fig-section-h4\">2. Komponenten, Entitäten &amp; Schnittstellen</h4>\n<ul class=\"fig-list\"><li><strong>Beteiligte Entitäten:</strong>\n<ul class=\"fig-list\"><li><strong>FrTp Sender:</strong> Lokale Instanz des FlexRay Transport Layers auf dem Sende-Steuergerät (verwaltet Verbindungskontexte, Puffer und State-Machines).\n</li><li><strong>FrTp Receiver:</strong> Peer-Instanz auf dem Ziel-Knoten (im Diagramm als leere Lebenslinie dargestellt, da kein Buszugriff stattfindet).\n</li><li><strong>PduR (impliziter oberer Kommunikationspartner):</strong> Quelle der Sende- und Abbruchanforderungen.\n</li></ul>\n</li><li><strong>Schnittstellen &amp; Service-APIs:</strong>\n<ul class=\"fig-list\"><li><code>FrTp_Transmit(PduIdType TxPduId, const PduInfoType* PduInfoPtr)</code>: Service-Aufruf des PduR zur Initiierung der Übertragung.\n</li><li><code>FrTp_TransmitCancel(PduIdType TxPduId)</code>: Steueranforderung des PduR zum Verwerfen einer ausstehenden PDU vor deren physischer Aussendung.\n</li></ul>\n</li></ul>\n<h4 class=\"fig-section-h4\">3. Dynamisches Verhalten &amp; Sequenzablauf</h4>\n<ol class=\"fig-list\"><li><strong>Sendeinitiierung (<code>FrTp_Transmit</code>):</strong>\n<ul class=\"fig-list\"><li>PduR ruft synchron <code>FrTp_Transmit</code> am FrTp Sender auf. FrTp belegt den internen Sende-Verbindungskanal (<em>Channel State Machine</em>) und bereitet die unsegmentierte PDU für den Versand vor.\n</li></ul>\n</li><li><strong>Abbruchanforderung (<code>FrTp_TransmitCancel</code>):</strong>\n<ul class=\"fig-list\"><li>Noch vor der Übergabe an das FlexRay Interface (<code>FrIf_Transmit</code>) fordert PduR den Abbruch via <code>FrTp_TransmitCancel(TxPduId)</code> an.\n</li><li>FrTp bricht den Übertragungsauftrag ab; es erfolgt keine Datenübertragung auf den FlexRay-Bus und somit keine Interaktion mit dem <em>FrTp Receiver</em>.\n</li></ul>\n</li></ol>\n<h4 class=\"fig-section-h4\">4. Normative Relevanz &amp; Entwickler-Hinweise</h4>\n<ul class=\"fig-list\"><li><strong>API-Benennung:</strong> Die Abbruchfunktion wird als <code>FrTp_TransmitCancel</code> bezeichnet (im Unterschied zu älteren Fassungen mit <code>FrTp_TransmitCancellation</code>).\n</li><li><strong>Schnittstellenfokus:</strong> Das Diagramm visualisiert ausschließlich den Aufruf von <code>FrTp_Transmit</code> und den darauffolgenden Abbruch über <code>FrTp_TransmitCancel</code>; asynchrone Fortschreibungen im Kontext einer MainFunction oder explizite Tx-Confirmations werden in dieser Fassung nicht dargestellt.\n</li><li><strong>Konfigurationsabhängigkeit:</strong> Die Verfügbarkeit der Abbruchfunktion erfordert die Aktivierung der entsprechenden Transmit-Cancellation-Unterstützung in der FrTp-BSW-Konfiguration.\n</li><li><strong>Puffer- und Sendezustand:</strong> Transmit Cancellation für unsegmentierte Übertragungen greift nur, solange die PDU noch nicht an das unterlagerte FlexRay Interface (<code>FrIf</code>) übergeben bzw. von diesem verarbeitet wurde.\n</li></ul>", "model": "gemini-3.8-flash (via agy)"}, {"id": "FIG-a6c0e7699c76abcd", "releases": ["R25-11"], "html": "<h4 class=\"fig-section-h4\">1. Diagrammtyp &amp; Architektur-Kontext</h4>\n<ul class=\"fig-list\"><li><strong>Klassifikation:</strong> Sequenzdiagramm / Timing-Ablaufdiagramm (AUTOSAR-spezifische Darstellung mit Lebenslinien und asynchronen Trigger-Ereignissen über der Zeitachse t).\n</li><li><strong>Funktionale Einordnung:</strong> AUTOSAR Classic Platform BSW, Communication Stack (ComStack). Das Diagramm spezifiziert das Verhalten des <strong>FlexRay ISO Transport Layer (FrTp / ISO 10681-2)</strong> bei einem vorzeitigen Sendeabbruch (<em>Transmit Cancellation</em>) einer unsegmentierten Botschaft (<em>Single Frame</em> / SF).\n</li><li><strong>Zweck:</strong> Darstellung des Entkopplungs- und Abbruchmechanismus zwischen oberer Schicht (<strong>PDU Router / PduR</strong>) und FrTp-Sendepuffer, bevor Daten auf den FlexRay-Bus bzw. an das <strong>FlexRay Interface (FrIf)</strong> übergeben werden.\n</li></ul>\n<h4 class=\"fig-section-h4\">2. Komponenten, Entitäten &amp; Schnittstellen</h4>\n<ul class=\"fig-list\"><li><strong>Beteiligte Entitäten:</strong>\n<ul class=\"fig-list\"><li><strong>FrTp Sender:</strong> Lokale Instanz des FlexRay Transport Layers auf dem Sende-Steuergerät (verwaltet Verbindungskontexte, Puffer und State-Machines).\n</li><li><strong>FrTp Receiver:</strong> Peer-Instanz auf dem Ziel-Knoten (im Diagramm als leere Lebenslinie dargestellt, da kein Buszugriff stattfindet).\n</li><li><strong>PduR (impliziter oberer Kommunikationspartner):</strong> Quelle der Sende- und Abbruchanforderungen.\n</li></ul>\n</li><li><strong>Schnittstellen &amp; Service-APIs:</strong>\n<ul class=\"fig-list\"><li><code>FrTp_Transmit(PduIdType TxPduId, const PduInfoType* PduInfoPtr)</code>: Service-Aufruf des PduR zur Initiierung der Übertragung.\n</li><li><code>FrTp_TransmitCancel(PduIdType TxPduId)</code>: Steueranforderung des PduR zum Verwerfen einer ausstehenden PDU vor deren physischer Aussendung.\n</li></ul>\n</li></ul>\n<h4 class=\"fig-section-h4\">3. Dynamisches Verhalten &amp; Sequenzablauf</h4>\n<ol class=\"fig-list\"><li><strong>Sendeinitiierung (<code>FrTp_Transmit</code>):</strong>\n<ul class=\"fig-list\"><li>PduR ruft synchron <code>FrTp_Transmit</code> am FrTp Sender auf. FrTp belegt den internen Sende-Verbindungskanal (<em>Channel State Machine</em>) und bereitet die unsegmentierte PDU für den Versand vor.\n</li></ul>\n</li><li><strong>Abbruchanforderung (<code>FrTp_TransmitCancel</code>):</strong>\n<ul class=\"fig-list\"><li>Noch vor der Übergabe an das FlexRay Interface (<code>FrIf_Transmit</code>) fordert PduR den Abbruch via <code>FrTp_TransmitCancel(TxPduId)</code> an.\n</li><li>FrTp bricht den Übertragungsauftrag ab; es erfolgt keine Datenübertragung auf den FlexRay-Bus und somit keine Interaktion mit dem <em>FrTp Receiver</em>.\n</li></ul>\n</li></ol>\n<h4 class=\"fig-section-h4\">4. Normative Relevanz &amp; Entwickler-Hinweise</h4>\n<ul class=\"fig-list\"><li><strong>API-Benennung:</strong> Die Abbruchfunktion wird als <code>FrTp_TransmitCancel</code> bezeichnet (im Unterschied zu älteren Fassungen mit <code>FrTp_TransmitCancellation</code>).\n</li><li><strong>Schnittstellenfokus:</strong> Das Diagramm visualisiert ausschließlich den Aufruf von <code>FrTp_Transmit</code> und den darauffolgenden Abbruch über <code>FrTp_TransmitCancel</code>; asynchrone Fortschreibungen im Kontext einer MainFunction oder explizite Tx-Confirmations werden in dieser Fassung nicht dargestellt.\n</li><li><strong>Konfigurationsabhängigkeit:</strong> Die Verfügbarkeit der Abbruchfunktion erfordert die Aktivierung der entsprechenden Transmit-Cancellation-Unterstützung in der FrTp-BSW-Konfiguration.\n</li><li><strong>Puffer- und Sendezustand:</strong> Transmit Cancellation für unsegmentierte Übertragungen greift nur, solange die PDU noch nicht an das unterlagerte FlexRay Interface (<code>FrIf</code>) übergeben bzw. von diesem verarbeitet wurde.\n</li></ul>", "model": "gemini-3.8-flash (via agy)"}], "trans": [{"from": "FIG-19de9c0be9c5e7fd", "to": "FIG-960de3ef7fe55f9d", "fr": "R4.0.3", "tr": "R4.1.3", "change": "normativ", "label": "normative Änderung", "html": "<ul class=\"fig-list\"><li><code>FrTp_TransmitCancellation</code>: API-Funktionsaufruf in <code>FrTp_TransmitCancel</code> umbenannt.\n</li><li><code>FrTp_MainFunction</code> und <code>PduR_FrTpTxConfirmation</code>: Zyklischer Scheduler-Aufruf und asynchrone Bestätigung an den PduR wurden aus dem Ablaufdiagramm entfernt.\n</li></ul>"}, {"from": "FIG-960de3ef7fe55f9d", "to": "FIG-8969dbd85dd7247b", "fr": "R4.1.3", "tr": "R4.2.2", "change": "keine", "label": "keine inhaltliche Änderung", "html": "<p class=\"fig-p\">Keine inhaltlichen Änderungen erkennbar.</p>"}, {"from": "FIG-8969dbd85dd7247b", "to": "FIG-f75d9cc9b0ef5f57", "fr": "R4.2.2", "tr": "R24-11", "change": "keine", "label": "keine inhaltliche Änderung", "html": "<p class=\"fig-p\">Keine inhaltlichen Änderungen erkennbar.</p>"}, {"from": "FIG-f75d9cc9b0ef5f57", "to": "FIG-a6c0e7699c76abcd", "fr": "R24-11", "tr": "R25-11", "change": "keine", "label": "keine inhaltliche Änderung", "html": "<p class=\"fig-p\">Keine inhaltlichen Änderungen erkennbar.</p>"}]};
